mapper.update:
UPDATE book
SET name         = #{name},
    author       = #{author},
    price        = #{price},
    publish_date = #{publishDate}
WHERE id = #{id}

mapper.select:
SELECT id, name, author, price, publish_date
FROM book
WHERE id = #{id}

SELECT id, name, author, price, publish_date
FROM (
    SELECT t.*, ROWNUM rn
    FROM (
        SELECT id, name, author, price, publish_date
        FROM book


                AND name LIKE '%' || #{name} || '%'


        ORDER BY id DESC
    ) t
    WHERE ROWNUM <= #{endRow}
)
WHERE rn >= #{startRow}
